-- Source discovery: firm newsrooms become feeds automatically; wider feed net.

ALTER TABLE public.pe_firm_sources
  ADD COLUMN IF NOT EXISTS feed_url text,
  ADD COLUMN IF NOT EXISTS discovered_at timestamptz,
  ADD COLUMN IF NOT EXISTS discovery_note text,
  ADD COLUMN IF NOT EXISTS headquarters text,
  ADD COLUMN IF NOT EXISTS focus text;
ALTER TABLE public.rss_feeds ADD COLUMN IF NOT EXISTS firm_id uuid REFERENCES public.pe_firm_sources(id) ON DELETE SET NULL;
DROP POLICY IF EXISTS "Staff can manage firm sources" ON public.pe_firm_sources;
CREATE POLICY "Staff can manage firm sources" ON public.pe_firm_sources FOR ALL TO authenticated
USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));

-- Lower middle market sponsors (US). Wrong or dead domains simply fail discovery and get a note.
ON CONFLICT (website_url) DO NOTHING;

-- Wider feed net. News-search RSS catches the deal press releases that never hit a wire category.
ON CONFLICT (url) DO NOTHING;

-- Feeds we know are dead
UPDATE public.rss_feeds SET is_active = false WHERE url IN ('https://api.axios.com/feed/pro-rata', 'https://www.institutionalinvestor.com/rss/alternatives');
